UPDATE posts SET address = CASE id WHEN 23 THEN '青森県青森市浪岡大字女鹿沢字野尻14-1' WHEN 26 THEN '長野県飯田市鼎切石5247-1' WHEN 29 THEN '山形県酒田市浜中粮畑33' WHEN 30 THEN '北海道川上郡標茶町標茶798-1' WHEN 31 THEN '北海道枝幸郡浜頓別町クッチャロ湖畔' WHEN 33 THEN '高知県宿毛市大島17' WHEN 34 THEN '秋田県秋田市雄和椿川字駒坂台4-1' WHEN 41 THEN '徳島県三好郡東みよし町足代1300' WHEN 42 THEN '高知県高岡郡越知町越知丙734-1' END, budget = CASE id WHEN 29 THEN 440 WHEN 30 THEN 380 WHEN 31 THEN 400 WHEN 34 THEN 300 ELSE 0 END, business_hours = CASE id WHEN 26 THEN '12月上旬まで' WHEN 29 THEN '4月11日〜11月8日' WHEN 30 THEN '5月1日〜10月31日（冬季休業）' WHEN 31 THEN '4月下旬〜10月末（天候により変動）' WHEN 34 THEN '4月下旬〜11月中旬' ELSE business_hours END WHERE id IN (23,26,29,30,31,33,34,41,42);
UPDATE posts SET best_season = CASE id WHEN 23 THEN '5月〜10月' WHEN 26 THEN '4月〜11月（春はツツジ、秋は紅葉）' WHEN 29 THEN '4月〜11月（夕日は日没前に戻れる日）' WHEN 30 THEN '6月〜9月（雲海は冷え込みと無風が条件）' WHEN 33 THEN '通年（だるま夕日は11月中旬〜2月上旬）' WHEN 34 THEN '5月〜10月' WHEN 42 THEN '通年（仁淀川の色は夏が鮮やか）' ELSE best_season END, business_hours = CASE id WHEN 23 THEN '通年（冬季は積雪のため要確認）' WHEN 33 THEN '通年' WHEN 41 THEN '通年' WHEN 42 THEN '通年' ELSE business_hours END WHERE id IN (23,26,29,30,31,33,34,41,42);
UPDATE posts SET rating = CASE id WHEN 23 THEN 5 WHEN 26 THEN 5 WHEN 29 THEN 4 WHEN 30 THEN 4 WHEN 31 THEN 5 WHEN 33 THEN 4 WHEN 34 THEN 5 WHEN 41 THEN 3 WHEN 42 THEN 4 END WHERE id IN (23,26,29,30,31,33,34,41,42);
